package player

// libmpv tests of player/mpv.rs, under the same names, plus one Go test that plays
// the synthetic Gate 1 media through the public Load. They need the real library:
// VIEWER_MPV_DLL=<path to vendor/mpv/libmpv-2.dll> (Rust: VIEWER_LIBMPV). Without it
// they skip, unless VIEWER_REQUIRE_LIBMPV is set. The media test also needs
// VIEWER_TEST_MEDIA=<directory of spike.mkv, spike.ass, audio2.mka>, generated by
// `spike.exe -gen <dir>` (docs/evidence/gate1-go-2026-11-22.md). Headless:
// vo=null, ao=null; no window, no sound, no keystroke.

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"
)

// libmpvPath is VIEWER_MPV_DLL, or skips the test.
func libmpvPath(t *testing.T) string {
	t.Helper()
	p := os.Getenv("VIEWER_MPV_DLL")
	if info, err := os.Stat(p); p != "" && err == nil && !info.IsDir() {
		return p
	}
	if os.Getenv("VIEWER_REQUIRE_LIBMPV") != "" {
		t.Fatal("libmpv required but not found (VIEWER_MPV_DLL)")
	}
	t.Skip("SKIPPED: libmpv not found (set VIEWER_MPV_DLL)")
	return ""
}

// recorder is the Rust tests' mpsc channel: an unbounded queue, so the sink never
// blocks the event loop.
type recorder struct {
	mu     sync.Mutex
	events []PlayerEvent
	next   int
	wake   chan struct{}
}

func newRecorder() *recorder { return &recorder{wake: make(chan struct{}, 1)} }

func (r *recorder) sink(ev PlayerEvent) {
	r.mu.Lock()
	r.events = append(r.events, ev)
	r.mu.Unlock()
	select {
	case r.wake <- struct{}{}:
	default:
	}
}

// recv is mpsc's recv_timeout: the next unread event, or false at the deadline.
func (r *recorder) recv(timeout time.Duration) (PlayerEvent, bool) {
	deadline := time.Now().Add(timeout)
	for {
		r.mu.Lock()
		if r.next < len(r.events) {
			ev := r.events[r.next]
			r.next++
			r.mu.Unlock()
			return ev, true
		}
		r.mu.Unlock()
		left := time.Until(deadline)
		if left <= 0 {
			return nil, false
		}
		select {
		case <-r.wake:
		case <-time.After(left):
		}
	}
}

// drain is mpsc's try_iter: every unread event.
func (r *recorder) drain() []PlayerEvent {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := append([]PlayerEvent(nil), r.events[r.next:]...)
	r.next = len(r.events)
	return out
}

// all is every event received so far, read or not.
func (r *recorder) all() []PlayerEvent {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]PlayerEvent(nil), r.events...)
}

func (r *recorder) waitFor(timeout time.Duration, pred func(PlayerEvent) bool) bool {
	deadline := time.Now().Add(timeout)
	for {
		ev, ok := r.recv(time.Until(deadline))
		if !ok {
			return false
		}
		if pred(ev) {
			return true
		}
	}
}

func isEnd(reason EndReason) func(PlayerEvent) bool {
	return func(ev PlayerEvent) bool {
		e, ok := ev.(EndFile)
		return ok && e.Reason == reason
	}
}

func isEvent(want PlayerEvent) func(PlayerEvent) bool {
	return func(ev PlayerEvent) bool { return ev == want }
}

func timePosAtLeast(s float64) func(PlayerEvent) bool {
	return func(ev PlayerEvent) bool {
		p, ok := ev.(TimePos)
		return ok && p.Seconds >= s
	}
}

func headlessConfig() MpvConfig {
	c := DefaultMpvConfig()
	c.Headless = true
	return c
}

func newHeadless(t *testing.T, lib string, config MpvConfig) (*MpvEngine, *recorder) {
	t.Helper()
	rec := newRecorder()
	e, err := NewMpvEngine(lib, config, rec.sink)
	if err != nil {
		t.Fatalf("engine: %v", err)
	}
	t.Cleanup(func() { _ = e.Shutdown() })
	return e, rec
}

// loadRaw is the escape hatch for engine tests that need mpv-only sources (lavfi).
func (e *MpvEngine) loadRaw(target string) error {
	return e.command("loadfile", target, "replace")
}

func property(e *MpvEngine, name string) any {
	if v, ok := e.Property(name); ok {
		return v
	}
	return nil
}

// serve is a local HTTP server for engine tests: it answers with route(path) and
// records each request as "<path> <token>".
func serve(t *testing.T, route func(path string) string) (int, func() []string) {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { l.Close() })
	var mu sync.Mutex
	var seen []string
	go func() {
		for {
			c, err := l.Accept()
			if err != nil {
				return
			}
			var head []byte
			buf := make([]byte, 1024)
			for !bytes.Contains(head, []byte("\r\n\r\n")) {
				n, err := c.Read(buf)
				if n > 0 {
					head = append(head, buf[:n]...)
				}
				if err != nil || n == 0 {
					break
				}
			}
			text := string(head)
			path := ""
			if parts := strings.Split(text, " "); len(parts) > 1 {
				path = parts[1]
			}
			token := "-"
			for _, line := range strings.Split(text, "\n") {
				if v, ok := strings.CutPrefix(strings.TrimRight(line, "\r"), "X-Emby-Token: "); ok {
					token = v
					break
				}
			}
			mu.Lock()
			seen = append(seen, path+" "+token)
			mu.Unlock()
			_, _ = io.WriteString(c, route(path))
			c.Close()
		}
	}()
	return l.Addr().(*net.TCPAddr).Port, func() []string {
		mu.Lock()
		defer mu.Unlock()
		return append([]string(nil), seen...)
	}
}

func httpResponse(status, extraHeader, body string) string {
	return fmt.Sprintf("HTTP/1.1 %s\r\n%sContent-Length: %d\r\nConnection: close\r\n\r\n%s", status, extraHeader, len(body), body)
}

func loadURL(e *MpvEngine, url string) error {
	src, err := ParseSource(url)
	if err != nil {
		return err
	}
	return e.Load(&PlaybackRequest{Source: url}, src)
}

func Test_https_sources_get_the_windows_roots_and_fail_closed(t *testing.T) {
	lib := libmpvPath(t)
	dir := filepath.Join(os.TempDir(), fmt.Sprintf("viewer-roots-é-%d", os.Getpid()))
	t.Cleanup(func() { os.RemoveAll(dir) })
	path := filepath.Join(dir, "tls-roots.pem")
	engineWith := func(roots string) *MpvEngine {
		c := headlessConfig()
		c.TLSRoots = roots
		e, err := NewMpvEngine(lib, c, nil)
		if err != nil {
			t.Fatalf("engine: %v", err)
		}
		return e
	}

	e := engineWith(path)
	if err := loadURL(e, "http://127.0.0.1:1/video"); err != nil {
		t.Fatal("http", err)
	}
	if _, err := os.Stat(path); err == nil {
		t.Fatal("no export for a plain HTTP source")
	}
	if got := property(e, "tls-ca-file"); got != "" {
		t.Fatal(got)
	}
	if err := loadURL(e, "HTTPS://127.0.0.1:1/video"); err != nil {
		t.Fatal("https", err)
	}
	pem, err := os.ReadFile(path)
	if err != nil || !strings.HasPrefix(string(pem), "-----BEGIN CERTIFICATE-----\n") {
		t.Fatal(err)
	}
	if got := property(e, "tls-ca-file"); got != path {
		t.Fatal(got)
	}
	_ = e.Shutdown()

	// No path configured: nothing to trust, OpenSSL refuses.
	e = engineWith("")
	if err := loadURL(e, "https://127.0.0.1:1/video"); err != nil {
		t.Fatal("https", err)
	}
	if got := property(e, "tls-ca-file"); got != "" {
		t.Fatal(got)
	}
	_ = e.Shutdown()

	// The export fails: nothing is loaded.
	e = engineWith(filepath.Join(path, "not-a-directory", "roots.pem"))
	err = loadURL(e, "https://127.0.0.1:1/video")
	var pe *PlayerError
	if !errors.As(err, &pe) || pe.Kind != CertificateStore {
		t.Fatal("export failure", err)
	}
	if got := property(e, "path"); got != nil {
		t.Fatal(got)
	}
	_ = e.Shutdown()
}

// Preferences of ADR 0035 reach libmpv: style options, subtitles off, and the
// audio stream picked by its index in the file.
func Test_applies_subtitle_style_and_track_preferences(t *testing.T) {
	lib := libmpvPath(t)
	e, rec := newHeadless(t, lib, headlessConfig())
	request := PlaybackRequest{
		Source: "http://127.0.0.1:1/video",
		Tracks: TrackSelection{Audio: PickStream(2), Subtitle: TrackPick{Kind: TrackOff}},
		SubtitleStyle: SubtitleStyle{
			Size: SizeLarger, Color: ColorYellow, Background: BackgroundBox,
			Position: PositionRaised, OverrideASS: true,
		},
	}
	src, _ := ParseSource(request.Source)
	if err := e.Load(&request, src); err != nil {
		t.Fatal("load", err)
	}
	// Every option name exists in this libmpv and reads back as set.
	got := e.Diagnostics().SubtitleOptions
	want := List[[2]string]{
		{"sub-scale", "1.500000"},
		{"sub-color", "#FFFFE14D"},
		{"sub-border-style", "background-box"},
		{"sub-back-color", "#B3000000"},
		{"sub-pos", "85.000000"},
		{"sub-align-y", "bottom"},
		{"sub-ass-override", "force"},
	}
	if fmt.Sprint(got) != fmt.Sprint(want) {
		t.Fatal(got)
	}
	if got := property(e, "sid"); got != "no" {
		t.Fatal(got)
	}

	// The second audio stream of the file, by its index; the defaults come back.
	e.mu.Lock()
	e.pendingTracks = request.Tracks
	e.mu.Unlock()
	if err := e.loadRaw("av://lavfi:testsrc2=size=160x120:duration=30[out0];sine=f=440[out1];sine=f=880[out2]"); err != nil {
		t.Fatal("loadfile", err)
	}
	if !rec.waitFor(10*time.Second, isEvent(FileLoaded{})) {
		t.Fatal("file loaded")
	}
	if got := property(e, "current-tracks/audio/ff-index"); got != "2" {
		t.Fatal(got)
	}
	defaults := PlaybackRequest{Source: "http://127.0.0.1:1/video"}
	if err := e.Load(&defaults, src); err != nil {
		t.Fatal("load", err)
	}
	for name, want := range map[string]string{
		"options/aid": "auto", "options/sid": "auto", "sub-ass-override": "no", "sub-color": "#FFFFFFFF",
	} {
		if got := property(e, name); got != want {
			t.Errorf("%s: %v", name, got)
		}
	}
}

// playWithToken loads url with a token in a headless engine and returns every
// event up to the final end of file.
func playWithToken(t *testing.T, lib, url string) []PlayerEvent {
	t.Helper()
	e, rec := newHeadless(t, lib, headlessConfig())
	src, err := ParseSource(url)
	if err != nil {
		t.Fatal(err)
	}
	request := PlaybackRequest{Source: url, HTTPHeaders: List[Header]{{"X-Emby-Token", "TEST-TOKEN"}}}
	if err := e.Load(&request, src); err != nil {
		t.Fatal("load", err)
	}
	var events []PlayerEvent
	deadline := time.Now().Add(30 * time.Second)
	for {
		ev, ok := rec.recv(time.Until(deadline))
		if !ok {
			t.Fatalf("no end of file: %v", events)
		}
		events = append(events, ev)
		if isEnd(EndError)(ev) || isEnd(EndEOF)(ev) {
			return events
		}
	}
}

func containsEvent(events []PlayerEvent, want PlayerEvent) bool {
	for _, ev := range events {
		if ev == want {
			return true
		}
	}
	return false
}

// loadFailingSegments loads an HLS list of `segments` entries that all answer HTTP 500.
func loadFailingSegments(t *testing.T, lib string, segments int, openLimit time.Duration) (*MpvEngine, *recorder, func() int) {
	t.Helper()
	var playlist strings.Builder
	playlist.WriteString("#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:6\n#EXT-X-PLAYLIST-TYPE:VOD\n")
	for n := range segments {
		fmt.Fprintf(&playlist, "#EXTINF:6.0,\nseg/%d.ts\n", n)
	}
	playlist.WriteString("#EXT-X-ENDLIST\n")
	list := playlist.String()
	port, seen := serve(t, func(path string) string {
		if strings.HasSuffix(path, ".m3u8") {
			return httpResponse("200 OK", "Content-Type: application/vnd.apple.mpegurl\r\n", list)
		}
		return httpResponse("500 Internal Server Error", "", "Stale file handle")
	})
	c := headlessConfig()
	c.OpenLimit = openLimit
	e, rec := newHeadless(t, lib, c)
	if err := loadURL(e, fmt.Sprintf("http://127.0.0.1:%d/main.m3u8", port)); err != nil {
		t.Fatal("load", err)
	}
	return e, rec, func() int {
		n := 0
		for _, l := range seen() {
			if strings.Contains(l, ".ts") {
				n++
			}
		}
		return n
	}
}

// ADR 0027: once FFmpeg gives up on the list, mpv reads it as a playlist of files.
// The first failure ends it: no second wave of requests, no series of errors.
func Test_a_failed_hls_list_is_not_walked_as_a_playlist(t *testing.T) {
	lib := libmpvPath(t)
	const segments = 100
	e, rec, segmentRequests := loadFailingSegments(t, lib, segments, 30*time.Second)
	// mpv ends the list itself with "Other" (a redirect) when it reads it as a playlist.
	if !rec.waitFor(25*time.Second, isEnd(EndError)) {
		t.Fatal("no failure")
	}
	time.Sleep(2 * time.Second)
	settled := segmentRequests()
	for _, ev := range rec.drain() {
		if isEnd(EndError)(ev) {
			t.Fatalf("a second failure: %v", ev)
		}
	}
	time.Sleep(time.Second)
	if got := segmentRequests(); got != settled {
		t.Fatalf("%d then %d segment requests", settled, got)
	}
	if settled >= 3*segments {
		t.Fatalf("%d segment requests", settled)
	}
	_ = e.Shutdown()
}

// ADR 0027: FFmpeg skips HLS segments that fail, one after the other, and neither
// loads the file nor ends it. The limit ends the opening and stops the requests.
func Test_failing_hls_segments_end_at_the_opening_limit(t *testing.T) {
	lib := libmpvPath(t)
	started := time.Now()
	_, rec, segments := loadFailingSegments(t, lib, 50_000, 2*time.Second)

	var events []PlayerEvent
	for {
		ev, ok := rec.recv(20 * time.Second)
		if !ok {
			break
		}
		events = append(events, ev)
		if _, end := ev.(EndFile); end {
			break
		}
	}
	last, _ := events[len(events)-1].(EndFile)
	if last.Reason != EndError || last.Error == nil || *last.Error != "le flux ne s'ouvre pas" {
		t.Fatalf("%v", events)
	}
	if containsEvent(events, FileLoaded{}) {
		t.Fatalf("%v", events)
	}
	elapsed := time.Since(started)
	if elapsed < 2*time.Second || elapsed >= 5*time.Second {
		t.Fatal(elapsed)
	}
	if segments() <= 1 {
		t.Fatal("the demuxer went on to the next segments")
	}

	// The real end of file follows, then no more requests.
	if !rec.waitFor(5*time.Second, isEnd(EndStopped)) {
		t.Fatal("no stopped end of file")
	}
	afterStop := segments()
	time.Sleep(500 * time.Millisecond)
	if got := segments(); got != afterStop {
		t.Fatalf("%d then %d", afterStop, got)
	}
}

// ADR 0025: the token stops at the server the request was meant for.
func Test_redirect_does_not_carry_the_token_to_another_host(t *testing.T) {
	lib := libmpvPath(t)
	other, otherSeen := serve(t, func(string) string { return httpResponse("404 Not Found", "", "") })
	port, seen := serve(t, func(string) string {
		return httpResponse("302 Found", fmt.Sprintf("Location: http://127.0.0.1:%d/leak\r\n", other), "")
	})
	events := playWithToken(t, lib, fmt.Sprintf("http://127.0.0.1:%d/stream", port))
	if containsEvent(events, FileLoaded{}) {
		t.Fatalf("%v", events)
	}
	if got := seen(); len(got) != 1 || got[0] != "/stream TEST-TOKEN" {
		t.Fatal(got)
	}
	if got := otherSeen(); len(got) != 0 {
		t.Fatal(got)
	}
}

// ADR 0025: a playlist from the server does not open local files. Without the
// protocol whitelist, FFmpeg reads and plays this one.
func Test_hls_playlist_cannot_open_a_local_file(t *testing.T) {
	lib := libmpvPath(t)
	wav := filepath.Join(os.TempDir(), fmt.Sprintf("viewer-test-%d.wav", os.Getpid()))
	var b bytes.Buffer
	le := func(v any) { _ = binary.Write(&b, binary.LittleEndian, v) }
	b.WriteString("RIFF")
	le(uint32(36 + 8000))
	b.WriteString("WAVEfmt ")
	le(uint32(16))
	le(uint16(1))
	le(uint16(1))
	le(uint32(8000))
	le(uint32(8000))
	le(uint16(1))
	le(uint16(8))
	b.WriteString("data")
	le(uint32(8000))
	b.Write(bytes.Repeat([]byte{128}, 8000))
	if err := os.WriteFile(wav, b.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
	defer os.Remove(wav)

	segment := "file:" + strings.ReplaceAll(wav, `\`, "/")
	port, _ := serve(t, func(path string) string {
		if path != "/index.m3u8" {
			return httpResponse("404 Not Found", "", "")
		}
		playlist := "#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:10\n#EXTINF:1,\n" + segment + "\n#EXT-X-ENDLIST\n"
		return httpResponse("200 OK", "Content-Type: application/vnd.apple.mpegurl\r\n", playlist)
	})
	events := playWithToken(t, lib, fmt.Sprintf("http://127.0.0.1:%d/index.m3u8", port))
	if containsEvent(events, FileLoaded{}) {
		t.Fatalf("%v", events)
	}
}

// Real libmpv, headless: load, tracks, seek, external subtitle, pause, teardown.
func Test_headless_engine_lifecycle(t *testing.T) {
	lib := libmpvPath(t)
	e, rec := newHeadless(t, lib, headlessConfig())
	if got := property(e, "stream-lavf-o"); got != streamLavfOptions {
		t.Fatal("reconnect options kept by mpv", got)
	}
	if got, _ := e.Property("demuxer-lavf-o"); !strings.Contains(got, "protocol_whitelist") {
		t.Fatal("protocol whitelist kept by mpv", got)
	}
	if got := property(e, "tls-verify"); got != "yes" {
		t.Fatal(got)
	}
	if got := property(e, "curl-enabled"); got != "no" {
		t.Fatal(got)
	}
	if got, _ := e.Property("network-timeout"); !strings.HasPrefix(got, networkTimeout+".") && got != networkTimeout {
		t.Fatal(got)
	}

	// External subtitle queued like Load does, added on FILE_LOADED.
	srt := filepath.Join(os.TempDir(), fmt.Sprintf("viewer-test-%d.srt", os.Getpid()))
	if err := os.WriteFile(srt, []byte("1\n00:00:00,000 --> 00:00:30,000\nSous-titre de test\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	defer os.Remove(srt)
	title, lang := "Complets", "fre"
	e.mu.Lock()
	e.pendingSubtitles = []pendingSubtitle{{target: srt, sub: ExternalSubtitle{Title: &title, Lang: &lang, Selected: true}}}
	e.mu.Unlock()
	if err := e.loadRaw("av://lavfi:testsrc2=size=320x240:rate=25:duration=30"); err != nil {
		t.Fatal("loadfile", err)
	}
	if !rec.waitFor(10*time.Second, isEvent(FileLoaded{})) {
		t.Fatal("file loaded")
	}
	if !rec.waitFor(10*time.Second, func(ev PlayerEvent) bool { p, ok := ev.(TimePos); return ok && p.Seconds > 0.5 }) {
		t.Fatal("playback advances")
	}

	diag := e.Diagnostics()
	if diag.VideoWidth == nil || *diag.VideoWidth != 320 || diag.MpvVersion == nil {
		t.Fatalf("%+v", diag)
	}

	if err := e.Command(PlayerCommand{Type: CmdSeekAbsolute, Seconds: 20}); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(10*time.Second, timePosAtLeast(19.9)) {
		t.Fatal("seek reaches target")
	}

	tracks, err := e.Tracks()
	if err != nil {
		t.Fatal(err)
	}
	var subs []Track
	for _, tr := range tracks {
		if tr.Kind == KindSub {
			subs = append(subs, tr)
		}
	}
	if len(subs) != 1 {
		t.Fatal("external subtitle listed", subs)
	}
	if !subs[0].External || !subs[0].Selected || subs[0].Title == nil || *subs[0].Title != "Complets" || subs[0].Lang == nil || *subs[0].Lang != "fre" {
		t.Fatalf("%+v", subs[0])
	}
	if err := e.Command(PlayerCommand{Type: CmdSetSubtitleTrack}); err != nil {
		t.Fatal(err)
	}
	if got := property(e, "sid"); got != "no" {
		t.Fatal(got)
	}

	if err := e.Command(PlayerCommand{Type: CmdSetPaused, Paused: true}); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(5*time.Second, isEvent(Paused{Paused: true})) {
		t.Fatal("paused")
	}

	// `keep-open` keeps the last frame: the end still comes as an Eof.
	if err := e.Command(PlayerCommand{Type: CmdSeekAbsolute, Seconds: 29}); err != nil {
		t.Fatal(err)
	}
	if err := e.Command(PlayerCommand{Type: CmdSetPaused, Paused: false}); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(10*time.Second, isEnd(EndEOF)) {
		t.Fatal("end of file reported with keep-open")
	}

	if err := e.Command(PlayerCommand{Type: CmdStop}); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(5*time.Second, isEnd(EndStopped)) {
		t.Fatal("stop ends file")
	}
	started := time.Now()
	_ = e.Shutdown()
	_ = e.Shutdown() // idempotent
	if time.Since(started) >= 5*time.Second {
		t.Fatal("teardown is prompt")
	}
}

func Test_missing_library_is_reported(t *testing.T) {
	_, err := NewMpvEngine("Z:/nope/libmpv-2.dll", DefaultMpvConfig(), nil)
	var pe *PlayerError
	if !errors.As(err, &pe) || pe.Kind != LibraryUnavailable {
		t.Fatal(err)
	}
}

// Not in Rust: the Gate 1 media (H.264 MKV, external ASS subtitle, second audio
// file) through ParseSource and the public Load, every command, then a teardown
// run off the test goroutine (ADR 0003): one Shutdown event, after which the
// engine answers NotOpen and reads nothing.
func Test_go_engine_plays_the_gate1_media_and_tears_down(t *testing.T) {
	lib := libmpvPath(t)
	dir := os.Getenv("VIEWER_TEST_MEDIA")
	mkv, ass := filepath.Join(dir, "spike.mkv"), filepath.Join(dir, "spike.ass")
	if _, err := os.Stat(mkv); dir == "" || err != nil {
		t.Skip("SKIPPED: set VIEWER_TEST_MEDIA to the directory of spike.mkv (spike.exe -gen)")
	}
	rec := newRecorder()
	e, err := NewMpvEngine(lib, headlessConfig(), rec.sink)
	if err != nil {
		t.Fatal(err)
	}
	src, err := ParseSource(mkv)
	if err != nil || src.Kind != SourceLocalFile {
		t.Fatal(src, err)
	}
	start := 2.0
	request := PlaybackRequest{
		Source:       mkv,
		StartSeconds: &start,
		Subtitles:    List[ExternalSubtitle]{{Source: ass, Title: ptr("Test"), Lang: ptr("fre"), Selected: true}},
	}
	if err := e.Load(&request, src); err != nil {
		t.Fatal("load", err)
	}
	if !rec.waitFor(10*time.Second, isEvent(FileLoaded{})) {
		t.Fatal("file loaded", rec.all())
	}
	if !rec.waitFor(10*time.Second, timePosAtLeast(2.5)) {
		t.Fatal("plays from the start position", rec.all())
	}
	var duration float64
	var subtitle *Track
	deadline := time.Now().Add(5 * time.Second)
	for (duration == 0 || subtitle == nil) && time.Now().Before(deadline) {
		for _, ev := range rec.all() {
			switch v := ev.(type) {
			case Duration:
				duration = v.Seconds
			case Tracks:
				for i := range v.Tracks {
					if v.Tracks[i].Kind == KindSub && v.Tracks[i].External {
						subtitle = &v.Tracks[i]
					}
				}
			}
		}
		time.Sleep(50 * time.Millisecond)
	}
	if duration < 59 || duration > 61 {
		t.Fatal("duration", duration)
	}
	if subtitle == nil || !subtitle.Selected || subtitle.Title == nil || *subtitle.Title != "Test" {
		t.Fatalf("external subtitle in a tracks event: %+v", subtitle)
	}
	if got := property(e, "options/start"); got != "2" {
		t.Error("start", got)
	}
	d := e.Diagnostics()
	if d.VideoCodec == nil || !strings.HasPrefix(*d.VideoCodec, "H.264") || d.VideoWidth == nil || *d.VideoWidth != 1280 ||
		d.Container == nil || *d.Container != "mkv" || d.HwdecCurrent == nil || d.Paused == nil || *d.Paused || len(d.SubtitleOptions) != 7 {
		b, _ := json.Marshal(d)
		t.Fatalf("%s", b)
	}
	if a, s := e.SelectedStreams(); a == nil || *a != 1 || s != nil {
		t.Fatal("selected streams", a, s)
	}
	if p, ok := e.PositionSeconds(); !ok || p < 2 {
		t.Fatal(p, ok)
	}
	one := int64(1)
	for _, c := range []struct {
		cmd       PlayerCommand
		prop, val string
	}{
		{PlayerCommand{Type: CmdSetVolume, Percent: 500}, "volume", "130.000000"},
		{PlayerCommand{Type: CmdSetSpeed, Speed: 0.1}, "speed", "0.250000"},
		{PlayerCommand{Type: CmdSetSpeed, Speed: 1}, "speed", "1.000000"},
		{PlayerCommand{Type: CmdSetAudioDelay, Seconds: 42}, "audio-delay", "10.000000"},
		{PlayerCommand{Type: CmdSetSubtitleDelay, Seconds: -0.5}, "sub-delay", "-0.500000"},
		{PlayerCommand{Type: CmdSetVideoFit, Fit: FitFill}, "panscan", "1.000000"},
		{PlayerCommand{Type: CmdSetVideoFit, Fit: FitStretch}, "keepaspect", "no"},
		{PlayerCommand{Type: CmdSetAudioTrack, ID: &one}, "aid", "1"},
		{PlayerCommand{Type: CmdSetNightMode, On: false}, "af", ""},
	} {
		if err := e.Command(c.cmd); err != nil {
			t.Fatalf("%+v: %v", c.cmd, err)
		}
		if got := property(e, c.prop); got != c.val {
			t.Errorf("%+v: %s = %v", c.cmd, c.prop, got)
		}
	}
	if err := e.Command(PlayerCommand{Type: CmdSetNightMode, On: true}); err != nil {
		t.Fatal(err)
	}
	if got, _ := e.Property("af"); !strings.Contains(got, "acompressor") {
		t.Error("night mode", got)
	}
	if err := e.Command(PlayerCommand{Type: CmdSeekRelative, Seconds: 10}); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(5*time.Second, isEvent(Seeked{})) {
		t.Fatal("seeked")
	}
	if err := e.Command(PlayerCommand{Type: CmdTogglePause}); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(5*time.Second, isEvent(Paused{Paused: true})) {
		t.Fatal("toggle pause")
	}
	for _, bad := range []PlayerCommand{{Type: CmdSeekAbsolute, Seconds: nanValue()}, {Type: CmdSetAudioDelay, Seconds: nanValue()}} {
		if err := e.Command(bad); err == nil || err.Error() != "source invalide : valeur non finie" {
			t.Errorf("%+v: %v", bad, err)
		}
	}
	bad := PlaybackRequest{Source: mkv, HTTPHeaders: List[Header]{{"X-A: b", "c"}}}
	if err := e.Load(&bad, src); err == nil || err.Error() != "source invalide : en-tête HTTP invalide" {
		t.Error(err)
	}
	nul := PlaybackRequest{Source: mkv, HTTPHeaders: List[Header]{{"X-A", "b\x00c"}}}
	if err := e.Load(&nul, src); err == nil || err.Error() != "source invalide : caractère NUL" {
		t.Error("NUL reached mpv", err)
	}
	if err := e.Command(PlayerCommand{Type: CmdSetAudioTrack, ID: ptr(int64(99))}); err != nil {
		t.Error("an unknown track id is mpv's to ignore", err)
	}

	// Teardown off the caller's goroutine, as the app shell must do it (ADR 0003).
	before := len(rec.all())
	started := time.Now()
	done := make(chan struct{})
	go func() { _ = e.Shutdown(); close(done) }()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("teardown hangs")
	}
	teardown := time.Since(started)
	_ = e.Shutdown()
	shutdowns := 0
	for _, ev := range rec.all()[before:] {
		if ev == (Shutdown{}) {
			shutdowns++
		}
	}
	if shutdowns != 1 {
		t.Fatalf("%d Shutdown events after teardown: %v", shutdowns, rec.all()[before:])
	}
	if last := rec.all()[len(rec.all())-1]; last != (Shutdown{}) {
		t.Fatal("Shutdown is the last event", last)
	}
	if _, ok := e.Property("time-pos"); ok {
		t.Fatal("a destroyed engine still reads")
	}
	if err := e.Command(PlayerCommand{Type: CmdStop}); !errors.Is(err, ErrNotOpen) {
		t.Fatal(err)
	}
	if d := e.Diagnostics(); d.MpvVersion != nil || len(d.SubtitleOptions) != 0 {
		t.Fatalf("%+v", d)
	}
	t.Logf("teardown %v, %d events", teardown, len(rec.all()))
}

func nanValue() float64 {
	z := 0.0
	return z / z
}

func Test_shutdown_from_the_sink_fails_loudly(t *testing.T) {
	lib := libmpvPath(t)
	var e *MpvEngine
	got := make(chan error, 1)
	var once sync.Once
	e, err := NewMpvEngine(lib, headlessConfig(), func(ev PlayerEvent) {
		if _, ok := ev.(FileLoaded); ok {
			once.Do(func() { got <- e.Shutdown() })
		}
	})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = e.Shutdown() })
	if err := e.loadRaw("av://lavfi:testsrc2=size=320x240:rate=25:duration=5"); err != nil {
		t.Fatal(err)
	}
	select {
	case err := <-got:
		if !errors.Is(err, ErrShutdownFromSink) {
			t.Fatal(err)
		}
	case <-time.After(10 * time.Second):
		t.Fatal("Shutdown from the sink blocked or the sink never ran")
	}
	// Nothing was torn down: a normal Shutdown still works and emits once.
	if err := e.Shutdown(); err != nil {
		t.Fatal(err)
	}
}

func Test_mpv_quitting_by_itself_emits_shutdown_twice(t *testing.T) {
	lib := libmpvPath(t)
	e, rec := newHeadless(t, lib, headlessConfig())
	if err := e.loadRaw("av://lavfi:testsrc2=size=320x240:rate=25:duration=5"); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(10*time.Second, isEvent(FileLoaded{})) {
		t.Fatal("file loaded")
	}
	if err := e.command("quit"); err != nil {
		t.Fatal(err)
	}
	if !rec.waitFor(10*time.Second, isEvent(Shutdown{})) {
		t.Fatal("event loop reports mpv's own Shutdown")
	}
	if err := e.Shutdown(); err != nil {
		t.Fatal(err)
	}
	count := 0
	for _, ev := range rec.all() {
		if _, ok := ev.(Shutdown); ok {
			count++
		}
	}
	events := rec.all()
	if count != 2 {
		t.Fatalf("Shutdown events: %d, want 2 (like Rust): %v", count, events)
	}
	if _, ok := events[len(events)-1].(Shutdown); !ok {
		t.Fatal("Shutdown is last", events)
	}
}
